    public MainView() {
        H1 heading = new H1("Items");
        add(heading);

        itemField = new TextField();
        itemField.setLabel("Item");
        add(itemField);

        HorizontalLayout buttonLayout = new HorizontalLayout();
        Button addButton = new Button("Add", event -> handleAdd());
        Button clearButton = new Button("Clear", event -> handleClear());
        buttonLayout.add(addButton, clearButton);
        add(buttonLayout);

        itemList = new UnorderedList();
        add(itemList);

        itemCount = new Span("Items: 0");
        add(itemCount);
    }

    private void handleAdd() {
        String value = itemField.getValue().trim();
        if (value.isEmpty()) {
            itemField.setInvalid(true);
        } else {
            itemField.setInvalid(false);
            ListItem item = new ListItem(value);
            itemList.add(item);
            itemField.clear();
            updateItemCount();
        }
    }

    private void handleClear() {
        itemList.removeAll();
        itemCount.setText("Items: 0");
    }

    private void updateItemCount() {
        int count = (int) itemList.getChildren().count();
        itemCount.setText("Items: " + count);
    }
